<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Plus, CalendarDays, Laptop, Inbox } from 'lucide-vue-next'
import { useApi, refreshData } from '../composables/query'
import { post } from '../services/api'
import { dateRange } from '../services/dates'
import { useSession } from '../stores/session'
import type { WorkRequest, CalendarData } from '../types'
import AsyncState from '../components/AsyncState.vue'
import StatusBadge from '../components/StatusBadge.vue'
import DataTable from '../components/DataTable.vue'
import ConfirmationDialog from '../components/ConfirmationDialog.vue'
import ApprovalCard from '../components/ApprovalCard.vue'
const route=useRoute(), router=useRouter(), session=useSession(), approvals=computed(()=>route.path==='/approvals'), status=ref(''), page=ref(0)
const {data,loading,error,refresh}=useApi<{items:WorkRequest[];total:number}>(()=>`/requests?scope=${approvals.value?'approvals':'mine'}&limit=20&offset=${page.value*20}${status.value?'&status='+status.value:''}`)
const selected=ref<WorkRequest|null>(null), action=ref(''), comment=ref(''), overrideReason=ref(''), busy=ref(false), failure=ref(''), availability=ref<CalendarData|null>(null)
watch([status,approvals],()=>page.value=0)
watch(data,value=>{const id=Number(route.query.selected);if(id&&!selected.value)selected.value=value?.items.find(r=>r.id===id)||null})
function decide(request:WorkRequest, value:string){selected.value=request;action.value=value;comment.value='';overrideReason.value='';failure.value=''}
async function submit(){if(!selected.value)return;busy.value=true;failure.value='';try{await post(`/requests/${selected.value.id}/${action.value}`,{comment:comment.value,override_reason:overrideReason.value});selected.value=null;action.value='';await refreshData();session.message('Request updated.')}catch(e){failure.value=(e as Error).message}finally{busy.value=false}}
function details(request:WorkRequest){router.push({path:'/calendar',query:{date:request.start_date}})}
</script>
<template><div class="page-heading"><div><div class="eyebrow">{{approvals?'KEEP YOUR TEAM MOVING':'ALL YOUR PLANS, IN ONE PLACE'}}</div><h1>{{approvals?'Approval inbox':'My requests'}}</h1><p>{{approvals?'A little clarity for every decision.':'From a first idea to a well-earned break.'}}</p></div><RouterLink v-if="!approvals" to="/request/vacation" class="btn primary"><Plus :size="17"/>New request</RouterLink></div><div class="filter-tabs" role="group" aria-label="Filter request status"><button v-for="[value,label] in [['','All requests'],['PENDING','Pending'],['APPROVED','Approved'],['CANCELLATION_REQUESTED','Cancellations'],['REJECTED','Declined']]" :key="value" :class="{selected:status===value}" @click="status=value">{{label}}</button></div><AsyncState :loading="loading" :error="error" :empty="!data?.items.length" @retry="refresh"><template #empty><Inbox :size="34"/><h3>You’re all caught up</h3><p>{{approvals?'Requests needing your attention will appear here.':'Your requests will appear here as you make plans.'}}</p></template><div v-if="approvals" class="approval-list"><ApprovalCard v-for="request in data?.items" :key="request.id" :request="request" @decide="decide" @details="details"/></div><section v-else class="panel"><DataTable :headers="['Request','Dates','Duration','Status','']"><tr v-for="request in data?.items" :key="request.id"><td><div class="request-cell"><span class="request-icon" :class="request.kind.toLowerCase()"><CalendarDays v-if="request.kind==='LEAVE'" :size="17"/><Laptop v-else :size="17"/></span><strong>{{request.label}}</strong></div></td><td>{{dateRange(request.start_date,request.end_date)}}</td><td>{{request.days}} days</td><td><StatusBadge :status="request.status"/></td><td><button class="text-link" @click="selected=request;action=''">Details</button></td></tr></DataTable></section><div class="pagination"><span>{{data?.total}} requests</span><button class="btn secondary" :disabled="page===0" @click="page--">Previous</button><button class="btn secondary" :disabled="(page+1)*20>=(data?.total||0)" @click="page++">Next</button></div></AsyncState><ConfirmationDialog :open="!!selected" :title="action?`${action[0]?.toUpperCase()}${action.slice(1)} request`:'Request details'" @close="selected=null;action='' "><template v-if="selected"><div class="detail-summary"><h3>{{selected.label}}</h3><p>{{dateRange(selected.start_date,selected.end_date)}} · {{selected.days}} days</p><StatusBadge :status="selected.status"/></div><template v-if="!action"><p v-if="selected.comment" class="request-comment">{{selected.comment}}</p><div v-for="(d,i) in selected.decisions" :key="i" class="decision-record"><strong>{{d.decision.replaceAll('_',' ')}}</strong><p>{{d.comment}}</p></div><div class="form-actions"><button v-if="selected.status==='DRAFT'" class="btn primary" @click="action='submit'">Submit draft</button><button v-if="['DRAFT','PENDING'].includes(selected.status)" class="btn secondary" @click="action='withdraw'">Withdraw request</button><button v-if="selected.status==='APPROVED'" class="btn secondary" @click="action='cancel'">Request cancellation</button></div></template><form v-else @submit.prevent="submit"><p class="muted" v-if="['cancel','withdraw'].includes(action)">{{action==='cancel'?'Your manager will review the cancellation before your balance is restored.':'This request will be cancelled without affecting your balance.'}}</p><label v-if="action==='reject'">Reason for declining<textarea v-model="comment" required minlength="3" maxlength="1000" rows="3"/></label><label v-if="action==='approve'&&selected.requires_justification">HR review justification<textarea v-model="overrideReason" required minlength="3" maxlength="1000" rows="3"/></label><p v-if="failure" class="error-box" role="alert">{{failure}}</p><div class="form-actions"><button type="button" class="btn secondary" @click="selected=null">Keep as is</button><button class="btn primary" :disabled="busy">{{busy?'Saving…':'Confirm '+action}}</button></div></form></template></ConfirmationDialog></template>
